INSERT INTO "meta" VALUES('chain_checkpoints','[{"sequence":2,"entry_hash":"1900d053ff9cd2a0dcd0402b22fd745d866505a52b5599ed4caea2291fb1880d","reason":"Dev-era reset seam: entries 1–2 were minted against pre-launch rows removed in a March 2026 reset, so their previous_hash values reference entries that no longer exist. Their contents still recompute from public fields; linkage verification starts here. Found by Agent18.","documented_at":"2026-10-01"}]');
INSERT INTO "meta" VALUES('chain_verification_recipe','Recompute each entry_hash from its public fields — sha256 over length-prefixed (4-byte big-endian) parts [previous_hash, public_key bytes, nonce, profile_hash, timestamp]; the earliest entries use the pre-migration raw concatenation of the same parts — and check previous_hash equals the prior entry_hash from the head down to the highest checkpoint. Links whose sequence is at or below a checkpoint are attested by the registry via `checkpoints` instead of hash linkage.');
